eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   destinations: () => (/* binding */ destinations),\n/* harmony export */   destinationsByTheme: () => (/* binding */ destinationsByTheme),\n/* harmony export */   getDestination: () => (/* binding */ getDestination)\n/* harmony export */ });\nconst W = (file)=>`https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}?width=1200`;\n/**\n * Curated Sri Lanka destination database.\n *\n * This module is the single factual source for destinations across the app:\n * the Explore page, the AI itinerary engine, and the rules-based planner all\n * read from here. Add new entries freely — no application code changes needed.\n */ const destinations = [\n    {\n        slug: 'colombo',\n        name: 'Colombo',\n        region: 'West Coast',\n        coords: [\n            6.9271,\n            79.8612\n        ],\n        summary: 'The island’s commercial capital — colonial arcades, temple drums and a fast-growing food scene.',\n        description: 'Colombo layers centuries of Portuguese, Dutch and British history over a working harbour city. Galle Face Green fills with kite flyers at dusk, the Pettah markets hum at dawn, and the gaslamp-lit arcades of the old Dutch Hospital now host some of the country’s best restaurants.',\n        image: W('Colombo, Sri Lanka.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Culture & Heritage',\n            'Food',\n            'Luxury',\n            'Family',\n            'Photography'\n        ],\n        activities: [\n            'Galle Face Green sunset walk',\n            'Pettah market tour',\n            'Gangaramaya Temple',\n            'Dutch Hospital dining precinct',\n            'Colombo National Museum'\n        ],\n        highlights: [\n            'Galle Face Green',\n            'Gangaramaya Temple',\n            'Pettah Floating Market'\n        ]\n    },\n    {\n        slug: 'negombo',\n        name: 'Negombo',\n        region: 'West Coast',\n        coords: [\n            7.2083,\n            79.8358\n        ],\n        summary: 'A laid-back fishing town and lagoon just north of the airport — golden sand, catamarans and Dutch canals.',\n        description: 'Negombo’s beaches and the Dutch-built canal network make it an effortless first or last stop. Watch the morning fish auction at the lagoon, cruise past mangroves, and eat crab caught the same day.',\n        image: W('Negombo Beach.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Beaches',\n            'Food',\n            'Family',\n            'Wellness'\n        ],\n        activities: [\n            'Lagoon boat safari',\n            'Fish market at dawn',\n            'Dutch canal cruise',\n            'Ayurvedic massage',\n            'Catamaran sailing'\n        ],\n        highlights: [\n            'Negombo Lagoon',\n            'Dutch Canal',\n            'St. Mary’s Church'\n        ]\n    },\n    {\n        slug: 'sigiriya',\n        name: 'Sigiriya',\n        region: 'Cultural Triangle',\n        coords: [\n            7.957,\n            80.7603\n        ],\n        summary: 'The Lion Rock — a 5th-century sky palace rising 200 metres above the cultural triangle.',\n        description: 'King Kashyapa’s fortress is Sri Lanka’s most iconic sight: frescoed maidens, the polished Mirror Wall, water gardens that still work after 1,500 years, and a summit palace with views to the horizon. Climb at dawn before the heat and the crowds.',\n        image: W('Lion Rock - Sigiriya, Sri Lanka.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Culture & Heritage',\n            'Adventure',\n            'Photography',\n            'Scenic'\n        ],\n        activities: [\n            'Sunrise Lion Rock climb',\n            'Pidurangala Rock sunset hike',\n            'Village tuk-tuk safari',\n            'Minneriya elephant gathering (seasonal)'\n        ],\n        highlights: [\n            'Lion Rock summit',\n            'Frescoes & Mirror Wall',\n            'Water Gardens'\n        ]\n    },\n    {\n        slug: 'kandy',\n        name: 'Kandy',\n        region: 'Hill Country',\n        coords: [\n            7.2906,\n            80.6337\n        ],\n        summary: 'The last royal capital, wrapped around a sacred lake and home of the Temple of the Tooth.',\n        description: 'Kandy was the seat of Sinhalese kings for 300 years and remains the spiritual heart of the island. The Temple of the Sacred Tooth Relic draws pilgrims in white, the Kandy Lake loop is made for slow evenings, and the Perahera festival fills the streets every July or August.',\n        image: W('Kandy Sri Lanka Temple of the tooth.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Culture & Heritage',\n            'Scenic',\n            'Food',\n            'Photography'\n        ],\n        activities: [\n            'Temple of the Tooth evening puja',\n            'Kandyan dance show',\n            'Royal Botanical Gardens Peradeniya',\n            'Kandy Lake stroll',\n            'Udawattekele forest hike'\n        ],\n        highlights: [\n            'Temple of the Tooth',\n            'Peradeniya Gardens',\n            'Kandy Lake'\n        ]\n    },\n    {\n        slug: 'nuwara-eliya',\n        name: 'Nuwara Eliya',\n        region: 'Hill Country',\n        coords: [\n            6.9497,\n            80.7891\n        ],\n        summary: '“Little England” at 1,868 metres — colonial cottages, cool air and the green cathedral of Ceylon’s tea country.',\n        description: 'The highest town in Sri Lanka keeps its British inheritance: the hill club, the 1910 post office, a racecourse at altitude. Around it, tea estates cascade in perfect lines and factory tours end with a tasting at source.',\n        image: W('Tea plantations near Nuwara Eliya, Sri Lanka - panoramio.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Scenic',\n            'Wellness',\n            'Luxury',\n            'Family',\n            'Food'\n        ],\n        activities: [\n            'Tea factory tour & tasting',\n            'Horton Plains & World’s End dawn trek',\n            'Gregory Lake boating',\n            'Victoria Park gardens',\n            'Golf at 1,800 m'\n        ],\n        highlights: [\n            'Horton Plains',\n            'Pedro Tea Estate',\n            'Gregory Lake'\n        ]\n    },\n    {\n        slug: 'ella',\n        name: 'Ella',\n        region: 'Hill Country',\n        coords: [\n            6.8667,\n            81.0466\n        ],\n        summary: 'A mountain village of waterfalls, tea trails and the Nine Arch Bridge — Sri Lanka’s favourite view.',\n        description: 'Ella sits high in the Uva hills where the climate turns soft and the air smells of eucalyptus. Hike Little Adam’s Peak at sunrise, watch the blue train cross the Nine Arch Viaduct, and cool off under Ravana Falls.',\n        image: W('Nine Arches Bridge in Ella.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Scenic',\n            'Adventure',\n            'Photography',\n            'Food'\n        ],\n        activities: [\n            'Little Adam’s Peak sunrise hike',\n            'Nine Arch Bridge train crossing',\n            'Ella Rock day hike',\n            'Ravana Falls',\n            'Cooking class with a local family'\n        ],\n        highlights: [\n            'Nine Arch Bridge',\n            'Little Adam’s Peak',\n            'Ella Rock'\n        ]\n    },\n    {\n        slug: 'yala',\n        name: 'Yala',\n        region: 'South Coast',\n        coords: [\n            6.3728,\n            81.5016\n        ],\n        summary: 'Leopard country — the world’s best odds of seeing the island’s apex predator in the wild.',\n        description: 'Yala’s Block I holds one of the highest leopard densities on Earth, alongside elephants, sloth bears, crocodiles and 200+ bird species. Dawn game drives in open jeeps end with breakfast on the beach; 2,000-year-old rock temples hide inside the park.',\n        image: W('Sri Lankan Leopard - Yala National Park.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Wildlife',\n            'Adventure',\n            'Photography',\n            'Luxury'\n        ],\n        activities: [\n            'Dawn leopard safari',\n            'Full-day game drive',\n            'Sithulpawwa rock temple',\n            'Coastal lagoon birding'\n        ],\n        highlights: [\n            'Leopard sightings',\n            'Elephant herds',\n            'Sithulpawwa temple'\n        ]\n    },\n    {\n        slug: 'udawalawe',\n        name: 'Udawalawe',\n        region: 'South Coast',\n        coords: [\n            6.4481,\n            80.8976\n        ],\n        summary: 'Open grassland and reservoirs where elephant herds roam against a backdrop of blue mountains.',\n        description: 'Udawalawe is the most reliable place in Asia to see wild elephants in large family groups, all year round. The Elephant Transit Home releases orphaned calves back to the wild — a moving stop for families.',\n        image: W('Udawalawe National Park.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Wildlife',\n            'Family',\n            'Adventure'\n        ],\n        activities: [\n            'Elephant safari at dawn',\n            'Elephant Transit Home feeding',\n            'Birdwatching on the reservoir'\n        ],\n        highlights: [\n            'Wild elephant herds',\n            'Elephant Transit Home',\n            'Udawalawe reservoir'\n        ]\n    },\n    {\n        slug: 'galle',\n        name: 'Galle',\n        region: 'South Coast',\n        coords: [\n            6.0535,\n            80.221\n        ],\n        summary: 'A 17th-century Dutch fort town on the ocean — ramparts, boutiques and the best sunsets on the coast.',\n        description: 'Galle Fort is a living walled town: Dutch churches, merchant houses turned galleries, and cafés in old warehouses. Walk the ramparts at golden hour when cricketers play on the greens below and the lighthouse catches the last light.',\n        image: W('Galle lighthouse A.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Culture & Heritage',\n            'Beaches',\n            'Food',\n            'Luxury',\n            'Photography'\n        ],\n        activities: [\n            'Ramparts sunset walk',\n            'Fort boutique & gallery crawl',\n            'Maritime Museum',\n            'Stilt fishermen at Koggala',\n            'Whale watching from Mirissa (seasonal)'\n        ],\n        highlights: [\n            'Galle Fort ramparts',\n            'Galle Lighthouse',\n            'Dutch Reformed Church'\n        ]\n    },\n    {\n        slug: 'mirissa',\n        name: 'Mirissa',\n        region: 'South Coast',\n        coords: [\n            5.9483,\n            80.4716\n        ],\n        summary: 'A perfect crescent bay — blue whales offshore, surf waves in, and candlelit seafood on the sand.',\n        description: 'Mirissa’s deep offshore waters host blue whales nearly year-round, while the bay itself is made for long swims and beginner surf. Coconut Tree Hill frames the sunset; the fishing harbour starts the day.',\n        image: W('Mirissa beach, Srilanka.jpg'),\n        durationDays: {\n            min: 1,\n            max: 3\n        },\n        themes: [\n            'Beaches',\n            'Wildlife',\n            'Adventure',\n            'Food',\n            'Family'\n        ],\n        activities: [\n            'Blue whale & dolphin cruise',\n            'Surf lessons',\n            'Coconut Tree Hill sunset',\n            'Secret Beach snorkelling',\n            'Parrot Rock climb'\n        ],\n        highlights: [\n            'Blue whale watching',\n            'Coconut Tree Hill',\n            'Secret Beach'\n        ]\n    },\n    {\n        slug: 'trincomalee',\n        name: 'Trincomalee',\n        region: 'East Coast',\n        coords: [\n            8.5874,\n            81.2152\n        ],\n        summary: 'One of the world’s great natural harbours — powder-white sand, sperm whales and temples on the headland.',\n        description: 'Trincomalee’s deep-water bay has drawn traders for two millennia. Up the coast, Uppuveli and Nilaveli beaches run soft and quiet; Pigeon Island’s reef is the east coast’s best snorkelling, and Koneswaram Temple crowns the bluff at Swami Rock.',\n        image: W('Trincomalee.jpg'),\n        durationDays: {\n            min: 2,\n            max: 3\n        },\n        themes: [\n            'Beaches',\n            'Culture & Heritage',\n            'Wildlife',\n            'Adventure',\n            'Family'\n        ],\n        activities: [\n            'Pigeon Island snorkelling',\n            'Whale & dolphin watching',\n            'Koneswaram Temple',\n            'Nilaveli beach days',\n            'Fort Frederick walk'\n        ],\n        highlights: [\n            'Nilaveli Beach',\n            'Pigeon Island',\n            'Koneswaram Temple'\n        ]\n    },\n    {\n        slug: 'arugam-bay',\n        name: 'Arugam Bay',\n        region: 'East Coast',\n        coords: [\n            6.8404,\n            81.834\n        ],\n        summary: 'Sri Lanka’s surf capital — a right-hand point break, barefoot cafés and lagoon elephants.',\n        description: 'From May to September Arugam Bay catches the east-coast swell, and its main point break is ranked among the best in Asia. Off-season it returns to a sleepy fishing village; the lagoon behind hides elephants and crocodiles.',\n        image: W('Arugam Bay.jpg'),\n        durationDays: {\n            min: 2,\n            max: 4\n        },\n        themes: [\n            'Beaches',\n            'Adventure',\n            'Wellness',\n            'Photography'\n        ],\n        activities: [\n            'Surf main point & Whiskey Point',\n            'Lagoon safari',\n            'Yoga by the beach',\n            'Elephant Rock sunset',\n            'Muhudu Maha Viharaya ruins'\n        ],\n        highlights: [\n            'Main Point surf break',\n            'Lagoon safari',\n            'Elephant Rock'\n        ]\n    },\n    {\n        slug: 'jaffna',\n        name: 'Jaffna',\n        region: 'North',\n        coords: [\n            9.6615,\n            80.0255\n        ],\n        summary: 'Tamil culture at its most vivid — temples ablaze with colour, island hopping and a cuisine all its own.',\n        description: 'Jaffna rewards travellers who make the long journey north: Nallur Kandaswamy Temple’s gold facade, the reconstructed library, causeways out to island villages, and dishes — crab curry, palmyrah sweets — you won’t taste further south.',\n        image: W('Nallur Kandaswamy temple.jpg'),\n        durationDays: {\n            min: 2,\n            max: 3\n        },\n        themes: [\n            'Culture & Heritage',\n            'Food',\n            'Photography'\n        ],\n        activities: [\n            'Nallur Kandaswamy Temple',\n            'Jaffna Library & fort',\n            'Delft Island day trip',\n            'Nagadeepa & Nainativu islands',\n            'Jaffna market food walk'\n        ],\n        highlights: [\n            'Nallur Festival (Jul–Aug)',\n            'Delft Island',\n            'Jaffna cuisine'\n        ]\n    },\n    {\n        slug: 'anuradhapura',\n        name: 'Anuradhapura',\n        region: 'Cultural Triangle',\n        coords: [\n            8.3114,\n            80.4037\n        ],\n        summary: 'The first great capital — colossal white dagobas and the world’s oldest documented tree.',\n        description: 'For 1,300 years Anuradhapura was the island’s seat of power and faith. Pilgrims in white still circle Ruwanwelisaya, and the sacred Bodhi tree has been tended continuously since 288 BC. Cycle the vast sacred city at dawn.',\n        image: W('Ruwanwelisaya Stupa Anuradhapura.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Culture & Heritage',\n            'Photography',\n            'Scenic'\n        ],\n        activities: [\n            'Sacred City cycle tour',\n            'Sri Maha Bodhi tree ceremony',\n            'Ruwanwelisaya at dusk',\n            'Isurumuniya rock temple',\n            'Mihintale sunrise climb'\n        ],\n        highlights: [\n            'Sri Maha Bodhi',\n            'Ruwanwelisaya',\n            'Jetavanaramaya'\n        ]\n    },\n    {\n        slug: 'polonnaruwa',\n        name: 'Polonnaruwa',\n        region: 'Cultural Triangle',\n        coords: [\n            7.9403,\n            81.0188\n        ],\n        summary: 'The medieval capital — rock-cut Gal Vihara Buddhas and a 12th-century planned city by a great lake.',\n        description: 'Polonnaruwa’s ruins are intimate and green, best explored by bicycle between the Royal Palace, the Sacred Quadrangle and the serene granite Buddhas of Gal Viharaya. Parakrama Samudra, the ancient reservoir, still waters the district.',\n        image: W('Gal Viharaya, Ancient City of Polonnaruwa, Sri Lanka.jpg'),\n        durationDays: {\n            min: 1,\n            max: 2\n        },\n        themes: [\n            'Culture & Heritage',\n            'Wildlife',\n            'Photography',\n            'Family'\n        ],\n        activities: [\n            'Ancient city cycle tour',\n            'Gal Viharara meditation',\n            'Parakrama Samudra sunrise',\n            'Minneriya & Kaudulla elephant safaris'\n        ],\n        highlights: [\n            'Gal Vihara Buddhas',\n            'Sacred Quadrangle',\n            'Parakrama Samudra'\n        ]\n    }\n];\nfunction getDestination(slug) {\n    return destinations.find((d)=>d.slug === slug);\n}\nfunction destinationsByTheme(theme) {\n    return destinations.filter((d)=>d.themes.includes(theme));\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/destinations.ts\n");

